      qtys j prim seq-int.at
      whole j prim seq-bool.at
      allocate-one
      stock items j prim seq-int.at prim swap prim seq-int.set
      allocated j prim seq-int.at prim seq-int.push
      j 1 prim +
      stock items qtys whole process-order-loop
    ] [
